            /// <summary>
            /// Check that <paramref name="that" /> is a JSON-able value, at any depth.
            /// </summary>
            /// <remarks>
            /// Neither a <c>null</c> nor a non-finite number has a representation as
            /// a JSON-able value, and <see cref="Nodes.JsonNode" /> rules out neither
            /// of the two statically.
            /// </remarks>
            /// <exception name="SerializationFailure">
            /// Thrown if either is found anywhere within <paramref name="that" />,
            /// carrying the path to the culprit within <paramref name="that" />.
            /// </exception>
            private static void CheckIsJsonAbleForSerialization(Nodes.JsonNode that)
            {
                switch (that)
                {
                    case Nodes.JsonArray jsonArray:
                        int index = 0;
                        foreach (Nodes.JsonNode? item in jsonArray)
                        {
                            try
                            {
                                if (item == null)
                                {
                                    throw new SerializationFailure(
                                        new Reporting.Error(
                                            "Expected a JSON-able value, but got a null"));
                                }
                                CheckIsJsonAbleForSerialization(item);
                            }
                            catch (SerializationFailure failure)
                            {
                                failure.Error.PrependSegment(
                                    new Reporting.IndexSegment(index));
                                throw;
                            }
                            index++;
                        }
                        break;

                    case Nodes.JsonObject jsonObject:
                        foreach (
                            KeyValuePair<string, Nodes.JsonNode?> member
                                in jsonObject)
                        {
                            try
                            {
                                if (member.Value == null)
                                {
                                    throw new SerializationFailure(
                                        new Reporting.Error(
                                            "Expected a JSON-able value, but got a null"));
                                }
                                CheckIsJsonAbleForSerialization(member.Value);
                            }
                            catch (SerializationFailure failure)
                            {
                                failure.Error.PrependSegment(
                                    new Reporting.KeySegment(member.Key));
                                throw;
                            }
                        }
                        break;

                    case Nodes.JsonValue jsonValue:
                        // NOTE (mristin):
                        // JSON knows neither an infinity nor a not-a-number, so neither is
                        // a JSON-able value, even though Nodes.JsonValue holds one happily
                        // if it was constructed programmatically.
                        if (
                            jsonValue.TryGetValue<double>(out double number)
                                && !System.Double.IsFinite(number))
                        {
                            throw new SerializationFailure(
                                new Reporting.Error(
                                    $"Expected a JSON-able value, but got the number {number}, " +
                                    "which is neither finite nor representable in JSON"));
                        }
                        break;

                    default:
                        throw new System.InvalidOperationException(
                            $"Unexpected node type: {that.GetType()}");
                }
            }

            /// <summary>
            /// Serialize <paramref name="that" /> to JSON as a JSON-able value.
            /// </summary>
            /// <remarks>
            /// The result is always a deep, independent copy of
            /// <paramref name="that" />, never <paramref name="that" /> itself.
            /// </remarks>
            /// <exception name="SerializationFailure">
            /// Thrown if <paramref name="that" /> contains a <c>null</c> or a non-finite
            /// number anywhere, at any depth.
            /// </exception>
            private static Nodes.JsonNode SerializeJsonValue(Nodes.JsonNode that)
            {
                // NOTE (mristin):
                // A System.Text.Json node remembers its parent, and attaching a node
                // which already has one throws
                // "System.InvalidOperationException: The node already has a parent".
                // The instance we are serializing owns ``that``, so putting ``that``
                // itself into the JSON object we are building would hand the same node
                // a second parent. Concretely, without the copy below:
                //
                //     var instance = new Our.SomeClass(someJsonObject);
                //     Jsonization.Serialize.ToJsonObject(instance);  // fine, attaches
                //     Jsonization.Serialize.ToJsonObject(instance);  // throws
                //
                // and the same happens on the first call already if two properties of
                // the instance, or two instances, share one node.
                //
                // ``that.DeepClone()`` would say this in one call, but ``DeepClone``
                // arrived only in .NET 8 and the generated code has to build against
                // .NET 6, where ``SerializeToNode`` is the spelling of the same thing.
                // Its return type is nullable only because it serializes an arbitrary
