        /// <summary>
        /// Serialize instances of meta-model classes to JSON elements.
        /// </summary>
        /// <example>
        /// Here is an example how to serialize an instance of IHasSemantics:
        /// <code>
        /// var anInstance = new Our.IHasSemantics(
        ///     // ... some constructor arguments ...
        /// );
        /// System.Text.Json.Nodes.JsonObject element = (
        ///     Serialize.ToJsonObject(
        ///         anInstance));
        /// </code>
        /// </example>
        public static class Serialize
        {
            /// <summary>
            /// Serialize an instance of the meta-model into a JSON object.
            /// </summary>
            /// <exception cref="SerializationException">
            /// Thrown when a value within <paramref name="that" /> instance can not be
            /// represented in JSON
            /// </exception>
            public static Nodes.JsonObject ToJsonObject(Our.IClass that)
            {
                try
                {
                    return Transformer.TransformIClass(that);
                }
                catch (SerializationFailure failure)
                {
                    throw new SerializationException(
                        Reporting.GenerateCSharpPath(failure.Error.PathSegments),
                        failure.Error.Cause);
                }
            }

            /// <summary>
            /// Serialize a literal of ModellingKind into a JSON string.
            /// </summary>
            /// <exception cref="SerializationFailure">
            /// Thrown when <paramref name="that" /> is no literal of ModellingKind at all.
            /// <see cref="ToJsonObject" /> converts it, so a caller which serializes
            /// a whole instance catches <see cref="SerializationException" /> instead.
            /// </exception>
            public static Nodes.JsonValue ModellingKindToJsonValue(Our.ModellingKind that)
            {
                string? text = Stringification.ToString(that);
                return Nodes.JsonValue.Create(text)
                    ?? throw new SerializationFailure(
                        new Reporting.Error(
                            $"Invalid ModellingKind: {that}"));
            }

